geometry_msgs::PoseStamped new_pose(double x, double y, double z, double w)
{
    geometry_msgs::PoseStamped pose;
    pose.header.frame_id = "map";
    pose.header.seq = 0;
    pose.header.stamp = ros::Time::now();
