void result_callback(const std_msgs::String &msg)
{
    if(msg.data == "success" && running)
    {
        rm_msgs::action pub_msg;
        if(actions.empty())
        {
            pub_msg.action.data = STOP;
            running = false;
        }
        else
        {
            while(actions.front().action >= 4)
            {
                pub_msg.action.data = MOVE; ///move
                pub_msg.path.header.frame_id = "map";
                pub_msg.path.header.seq = 0;
                pub_msg.path.header.stamp = ros::Time::now();
                int x = actions.front().x;
                int y = actions.front().y;
                pub_msg.path.poses.push_back(new_pose((x - 1) * SQUARE_LENGTH,
                        (y - 1) * SQUARE_LENGTH, 0, 0));
                actions.pop();
                /*if(actions.front().action < 4) break;
                double ddx = (double)(actions.front().x - x) / 5.0;
                double ddy = (double)(actions.front().y - y) / 5.0;
                for(int i = 1; i <= 4; i++)
                    pub_msg.path.poses.push_back(new_pose((x + ddx * i - 1) * SQUARE_LENGTH,
                                                          (y + ddy * i - 1) * SQUARE_LENGTH, 0, 0));*/
            }
            if(pub_msg.action.data == MOVE)
            {
                pub.publish(pub_msg);
                return;
            }
            int tower = get_tower(actions.front().x, actions.front().y);
            pub_msg.action.data = actions.front().action;
            if(actions.front().action == OCCUPY)
            {
                pub_msg.path.header.frame_id = "map";
                pub_msg.path.header.seq = 0;
                pub_msg.path.header.stamp = ros::Time::now();
                pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH, (actions.front().y - 1) * SQUARE_LENGTH, 0, 0));
            }
            if(actions.front().action == PUSH_CUP)
            {
                int side = get_tower_side(tower, actions.front().x, actions.front().y);
                double diff = 0.0;
                if(is_from_front(actions.front().x, actions.front().y, me)) diff = CUP_FRONT_DIFF + actions.front().cup_index * CUP_PER_DIFF;
                else if(is_from_left(actions.front().x, actions.front().y, me)) diff = CUP_LEFT_DIFF;
                else diff = CUP_RIGHT_DIFF;
                switch (side)
                {
                    case SIDE_UP:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH + SQUARE_CUP_DIFF,
                                                              (actions.front().y - 1) * SQUARE_LENGTH - diff, 0, - PI / 2));
                        break;
                    }
                    case SIDE_LEFT:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH + diff,
                                                              (actions.front().y - 1) * SQUARE_LENGTH + SQUARE_CUP_DIFF, 0, 0));
                        break;
                    }
                    case SIDE_DOWN:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH - SQUARE_CUP_DIFF,
                                                              (actions.front().y - 1) * SQUARE_LENGTH + diff, 0, PI / 2));
                        break;
                    }
                    case SIDE_RIGHT:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH - diff,
                                                              (actions.front().y - 1) * SQUARE_LENGTH - SQUARE_CUP_DIFF, 0, PI));
                        break;
                    }
                    default:
                        std::cout << "result_callback():WTF???\n";
                }
            }
            else if(actions.front().action == PUSH_BALL)
            {
                int side = get_tower_side(tower, actions.front().x, actions.front().y);
                double diff = pub_msg.ball_index.data * BALL_PER_DIFF;
                int first_box = 1;
                while(actions.front().ball_in_box[first_box] <= 0)
                {
                    first_box++;
                    if(first_box >= 5) break;
                }
                pub_msg.ball_index.data = actions.front().tower_ball_number[tower][get_tower_side(tower, actions.front().x, actions.front().y)]
                                          - actions.front().ball;
                for (int i = first_box; i < first_box + actions.front().ball; ++i) pub_msg.ball.data += (1 << (i - first_box));
                diff += first_box * BALL_PER_DIFF;
                if(is_from_front(actions.front().x, actions.front().y, me)) diff += BALL_FRONT_DIFF;
                else if(is_from_left(actions.front().x, actions.front().y, me)) diff += BALL_LEFT_DIFF;
                else diff += BALL_RIGHT_DIFF;
                switch (side)
                {
                    case SIDE_UP:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH + SQUARE_BALL_DIFF,
                                                              (actions.front().y - 1) * SQUARE_LENGTH - diff, 0, PI));
                        break;
                    }
                    case SIDE_LEFT:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH + diff,
                                                              (actions.front().y - 1) * SQUARE_LENGTH + SQUARE_BALL_DIFF, 0, - PI / 2));
                        break;
                    }
                    case SIDE_DOWN:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH - SQUARE_BALL_DIFF,
                                                              (actions.front().y - 1) * SQUARE_LENGTH + diff, 0, 0));
                        break;
                    }
                    case SIDE_RIGHT:
                    {
                        pub_msg.path.header.frame_id = "map";
                        pub_msg.path.header.seq = 0;
                        pub_msg.path.header.stamp = ros::Time::now();
                        pub_msg.path.poses.push_back(new_pose((actions.front().x - 1) * SQUARE_LENGTH + diff,
                                                              (actions.front().y - 1) * SQUARE_LENGTH - SQUARE_BALL_DIFF, 0, PI / 2));
                        break;
                    }
                    default:
                        std::cout << "result_callback():WTF???\n";
                }
            }
            actions.pop();
        }
        pub.publish(pub_msg);
    }
}

void status_callback(const rm_msgs::status &msg)
{
    if(running)
    {
        if(msg.round_team.data != msg.me.data && msg.remain_square.data > 0 && msg.remain_tick.data > 0)
        {
            running = false;
            while(!actions.empty()) actions.pop();
        }
        return;
    }
    if(msg.round_team.data != msg.me.data && msg.remain_square.data > 0 && msg.remain_tick.data > 0) return;
    if(msg.round_team.data == msg.me.data && msg.remain_square.data < 10 && msg.remain_tick.data < 30) return;
    running = true;
    for (int i = 0; i < 7; i++)
        stat[1].tower_power[i + 1][RED] = msg.tower_power_red[i].data;
    for (int i = 0; i < 7; i++)
        stat[1].tower_power[i + 1][BLUE] = msg.tower_power_blue[i].data;
    for (int i = 0; i < 7; ++i)
        stat[1].tower_occupy[i + 1] = get_tower_occupy(1, i + 1);
    pos_x[RED] = msg.car_pos_x_red.data;
    pos_y[RED] = msg.car_pos_y_red.data;
    pos_x[BLUE] = msg.car_pos_x_blue.data;
    pos_y[BLUE] = msg.car_pos_y_blue.data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[1][j + 1] = msg.graph_occupy_1[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[2][j + 1] = msg.graph_occupy_2[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[3][j + 1] = msg.graph_occupy_3[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[4][j + 1] = msg.graph_occupy_4[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[5][j + 1] = msg.graph_occupy_5[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[6][j + 1] = msg.graph_occupy_6[j].data;
    for (int j = 0; j < 9; j++) stat[1].graph_occupy[7][j + 1] = msg.graph_occupy_7[j].data;
    me = msg.me.data;
    ///who i am
    if (me == BLUE) enemy = RED;
    else enemy = BLUE;
    ///set origin status
    stat[1].x = pos_x[me];
    stat[1].y = pos_y[me];
    stat[1].rest_time = tot_time;
    stat[1].score = 0;
    stat[1].weight = 0;
    stat[1].action = 0;
    stat[1].ball = 0;
    stat[1].father = 0;
    stat[1].rest_square = max_square;
    update_graph_status(1);
    ///WARNING:C++11
    q.push(node{1, 0});
    tot = 1;
    std::cout << "started\n";
    print_status(stat[1]);
    work();
    std_msgs::String suc_str;
    suc_str.data = "success";
    result_pub.publish(suc_str);
}

