///check if the car can move to this square
bool check(int x, int y)
{
    if(x <= 0 || x >= 8 || y <= 0 || y >= 10) return false;
    return !((x == 1 && y == 3) || (x == 1 && y == 7) || (x == 4 && y == 1) ||
             (x == 4 && y == 5) || (x == 4 && y == 9) || (x == 7 && y == 3) || (x == 7 && y == 7)
             || (x == pos_x[enemy] && y == pos_y[enemy]));
}

///get the tower near the square (x, y)
int get_tower(int x, int y)
{
    if((x == 1 && y == 2) || (x == 2 && y == 3) || (x == 1 && y == 4)) return 1;
    if((x == 1 && y == 6) || (x == 2 && y == 7) || (x == 1 && y == 8)) return 2;
    if((x == 3 && y == 1) || (x == 4 && y == 2) || (x == 5 && y == 1)) return 3;
    if((x == 3 && y == 5) || (x == 5 && y == 5) || (x == 4 && y == 4) || (x == 4 && y == 6)) return 4;
    if((x == 3 && y == 9) || (x == 4 && y == 8) || (x == 5 && y == 9)) return 5;
    if((x == 7 && y == 2) || (x == 6 && y == 3) || (x == 7 && y == 4)) return 6;
    if((x == 7 && y == 6) || (x == 6 && y == 7) || (x == 7 && y == 8)) return 7;
    return 0;
}

///return who occupy this tower
int get_tower_occupy(int index, int tower)
{
    if(stat[index].tower_power[tower][RED] > stat[index].tower_power[tower][BLUE]) return RED;
    if(stat[index].tower_power[tower][RED] < stat[index].tower_power[tower][BLUE]) return BLUE;
    return 0;
}

///get the connected towers around the block
void occupy_dfs(int index, int x, int y, int player)
{
    if(x <= 0 || x >= 8 || y <= 0 || y >= 10) return;
    if(stat[index].graph_occupy[x][y] != player) return;
    if(visited[x][y]) return;
    visited[x][y] = true;
    if(get_tower(x, y) && stat[index].tower_occupy[get_tower(x, y)] == player) tower_connected[get_tower(x, y)] = true;
    occupy_dfs(index, x + 1, y, player);
    occupy_dfs(index, x - 1, y, player);
    occupy_dfs(index, x, y + 1, player);
    occupy_dfs(index, x, y - 1, player);
}

///get the occupy status of this car
int get_occupy_status(int index, int player)
{
    int tower_count = 0;
    int x = stat[index].x;
    int y = stat[index].y;
    memset(tower_connected, 0, sizeof(tower_connected));
    memset(visited, 0, sizeof(visited));
    ///note:assume the square is the player's
    int t = stat[index].graph_occupy[x][y];
    stat[index].graph_occupy[x][y] = player;
    occupy_dfs(index, x, y, player);
    stat[index].graph_occupy[x][y] = t;
    for (int k = 0; k < 10; ++k)
        if(tower_connected[k]) tower_count++;
    if(tower_count >= 3) return STRONG_OCCUPY;
    if(tower_count > 0) return WEAK_OCCUPY;
    return CANT_OCCUPY;
}

///check if the action is legal
bool check_action(int index, int action)
{
    if(action >= MOVE_UP && action <= MOVE_RIGHT)
        if(check(stat[index].x + dx[action], stat[index].y + dy[action]) && stat[index].rest_time >= min_time + move_time) return true;
    ///note:the last condition is made to avoid multiply placing cup or ball
    if(action == PUSH_CUP)
        if(get_tower(stat[index].x + dx[action], stat[index].y + dy[action]) &&
           stat[index].rest_ball >= 1 && stat[index].rest_cup >= 1 &&
            stat[index].tower_occupy[get_tower(stat[index].x + dx[action], stat[index].y + dy[action])] != me
                && stat[index].rest_time >= min_time + cup_time) return true;
    if(action == PUSH_BALL) if(get_tower(stat[index].x, stat[index].y) && stat[index].rest_ball >= 1 &&
        stat[index].tower_occupy[get_tower(stat[index].x + dx[action],stat[index].y + dy[action])] != me
            && stat[index].rest_time >= min_time + ball_time) return true;
    ///note:the last condition is made to avoid multiply occupying
    if(action == OCCUPY) if(get_occupy_status(index, me) &&
        stat[index].graph_occupy[stat[index].x][stat[index].y] != me &&
            stat[index].graph_status[stat[index].x][stat[index].y] != STRONG_OCCUPY &&
                stat[index].rest_time >= min_time + occupy_time) return true;
    return false;
}

///choose a random action
int random_action(int index)
{
    vector <int> actions;
    for (int i = 1; i < 8; ++i) if(check_action(index, i)) actions.push_back(i);
    return actions[rand() % actions.size()];
}

