///sum the total score for each player
void sum(int index, int *blue, int *red)
{
    *blue = 0;
    *red = 0;
    for (int i = 1; i <= 7; i++)
        for (int j = 1; j <= 9; ++j)
        {
            if(stat[index].graph_occupy[i][j] == BLUE)
            {
                if(stat[index].graph_status[i][j] == WEAK_OCCUPY) *blue += occupy_weight_weak;
                else *blue += occupy_weight_strong;
            }
            else if(stat[index].graph_occupy[i][j] == RED)
            {
                if(stat[index].graph_status[i][j] == WEAK_OCCUPY) *red += occupy_weight_weak;
                else *red += occupy_weight_strong;
            }
        }
    for (int i = 0; i < 10; ++i)
    {
        if(stat[index].tower_occupy[i] == RED) *red += occupy_tower_weight;
        if(stat[index].tower_occupy[i] == BLUE) *blue += occupy_tower_weight;
        *red += stat[index].tower_power[i][RED] * tower_power_weight;
        *blue += stat[index].tower_power[i][BLUE] * tower_power_weight;
    }
    //std::cout<<*red<<" "<<*blue<<std::endl;
}

int get_score(int init, int index, int player)
{
    int red, blue, score, score_blue, score_red;
    sum(init, &score_blue, &score_red);
    sum(index, &blue, &red);
    //cout<<red<<" "<<blue<<endl;
    if(player == RED) score = red - score_red + score_blue - blue;
    else score = blue - score_blue + score_red - red;
    //cout<<score<<endl;
    return score;
}

///the dfs part of simulation
///note:this function uses stat[0] as a temp
int simulate_dfs(status simulate_stat, int index)
{
    if(simulate_stat.rest_time <= min_time || simulate_stat.rest_square <= min_square) return get_score(index, 0, me);
    int action;
    stat[0] = simulate_stat;
    action = random_action(0);
    stat[0].action = action;
    stat[0].father = 0;
    //cout<<action<<endl;
    switch (action)
    {
        case OCCUPY:
        {
            stat[0].graph_occupy[stat[0].x][stat[0].y] = me;
            stat[0].graph_status[stat[0].x][stat[0].y] = get_occupy_status(0, me);
            stat[0].rest_time -= occupy_time;
            break;
        }
        case PUSH_BALL:
        {
            stat[0].rest_ball--;
            stat[0].rest_time -= ball_time;
            stat[0].tower_power[get_tower(stat[0].x, stat[0].y)][me]++;
            stat[0].tower_occupy[get_tower(stat[0].x, stat[0].y)] = get_tower_occupy(0, get_tower(stat[0].x, stat[0].y));
            break;
        }
        case PUSH_CUP:
        {
            stat[0].rest_ball--;
            stat[0].rest_cup--;
            stat[0].rest_time -= cup_time;
            stat[0].tower_power[get_tower(stat[0].x, stat[0].y)][me] += 4;
            stat[0].tower_occupy[get_tower(stat[0].x, stat[0].y)] = get_tower_occupy(0, get_tower(stat[0].x, stat[0].y));
            //cout<<stat[0].tower_occupy[get_tower(stat[0].x, stat[0].y)]<<endl;
            break;
        }
            ///move
        default:
        {
            stat[0].rest_square--;
            stat[0].rest_time -= move_time;
            stat[0].x += dx[action];
            stat[0].y += dy[action];
            if(stat[0].graph_occupy[stat[0].x][stat[0].y] == enemy) stat[0].score += pass_weight;
        }
    }
    return simulate_dfs(stat[0], index);
}

///simulate the status to get a assume weight
int simulate(int index)
{
    int total_score = 0, last_score;
    ///step1:choose a random way until this status can not do anything
    for (int i = 0; i < 100; ++i)
    {
        last_score = total_score;
        for (int j = 0; j < stat[index].rest_time / 100; ++j)
            total_score = max(simulate_dfs(stat[index], index), total_score);
        if (total_score == last_score) break;
    }
    ///step2:count and return the score of this status
    return total_score;
}

///priority and Monte Carlo Method BFS
void work()
{
    while(!q.empty())
    {
        ///step1:choose the status which has the max weight
        node n = q.top();
        q.pop();
        ///if this status can not do anything, return and print
        if(stat[n.index].rest_time <= min_time || stat[n.index].rest_square <= min_square)
        {
            print(n.index);
            while(!q.empty()) q.pop();
            return;
        }
        ///step2:expand every possible choice of this status
        ///step3:simulate many times to get its average reward
        for(int i = 1; i < 8; i++)
        {
            if(!check_action(n.index, i)) continue;
            tot++;
            stat[tot] = stat[n.index];
            stat[tot].action = i;
            stat[tot].father = n.index;
            switch (i)
            {
                case OCCUPY:
                {
                    stat[tot].graph_occupy[stat[tot].x][stat[tot].y] = me;
                    stat[tot].graph_status[stat[tot].x][stat[tot].y] = get_occupy_status(tot, me);
                    stat[tot].rest_time -= occupy_time;
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                case PUSH_BALL:
                {
                    stat[tot].rest_ball--;
                    stat[tot].rest_time -= ball_time;
                    stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me]++;
                    stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                case PUSH_CUP:
                {
                    stat[tot].rest_ball--;
                    stat[tot].rest_cup--;
                    stat[tot].rest_time -= cup_time;
                    stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me] += 4;
                    stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                ///move
                default:
                {
                    stat[tot].rest_square--;
                    stat[tot].rest_time -= move_time;
                    stat[tot].x += dx[i];
                    stat[tot].y += dy[i];
                    if(stat[tot].graph_occupy[stat[tot].x][stat[tot].y] == enemy) stat[tot].score += pass_weight;
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                }
            }
            ///step4:add this status to the queue
            q.push(node{tot, stat[tot].weight});
        }
    }
}

