double uct(int father, int child)
{
    //cout << stat[child].score << " " << stat[father].score << " " << (double)stat[father].expand << " "
    // << (double)stat[child].expand << endl;
    double result = (double)stat[child].score / (double)stat[father].score +
        10.0 * sqrt((double)log(stat[father].expand) / (double)stat[child].expand);
    //cout << result << endl;
    return result;
}

//choice random action until this status can not do anything and then return the score of the end status
int estimate(int index)
{
    if(stat[index].rest_time <= min_time || stat[index].rest_square <= min_square)
    {
        int red, blue, score;
        sum(index, &blue, &red);
        //std::cout<<red<<" "<<blue<<std::endl;
        if(me == RED) score = red - score_red + score_blue - blue;
        else score = blue - score_blue + score_red - red;
        return score;
    }
    //TODO:make a function to make these steps better
    //TODO:make a proper random function
    int action;
    while(true)
    {
        action = random_action();
        if(check_action(index, action)) break;
    }
    switch (action)
    {
        case OCCUPY:
        {
            int occupy_status = get_occupy_status(index, me);
            if(occupy_status == CANT_OCCUPY) return estimate(index);
            if(stat[index].graph_occupy[stat[index].x][stat[index].y] == me ||
               stat[index].graph_status[stat[index].x][stat[index].y] == STRONG_OCCUPY) return estimate(index);
            stat[++tot] = stat[index];
            stat[tot].score = 0;
            stat[tot].expand = 0;
            memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
            stat[tot].graph_occupy[stat[tot].x][stat[tot].y] = me;
            stat[tot].graph_status[stat[tot].x][stat[tot].y] = occupy_status;
            stat[tot].father = index;
            stat[tot].action = OCCUPY;
            stat[index].child_status[OCCUPY] = tot;
            stat[tot].rest_time -= occupy_time;
            int t = tot;
            int score = estimate(tot);
            stat[t].score += score;
            return score;
        }
        case PUSH_BALL:
        {
            int tower = get_tower(stat[index].x, stat[index].y);
            if(stat[index].tower_occupy[tower] == me) return estimate(index);
            stat[++tot] = stat[index];
            stat[tot].score = 0;
            stat[tot].expand = 0;
            memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
            stat[tot].rest_ball--;
            stat[tot].rest_time -= ball_time;
            stat[tot].tower_power[tower][me]++;
            if(stat[tot].tower_power[tower][me] > stat[tot].tower_power[tower][enemy]) stat[tot].tower_occupy[tower] = me;
            stat[tot].father = index;
            stat[tot].action = PUSH_BALL;
            stat[index].child_status[PUSH_BALL] = tot;
            int t = tot;
            int score = estimate(tot);
            stat[t].score += score;
            return score;
        }
        case PUSH_CUP:
        {
            int tower = get_tower(stat[index].x, stat[index].y);
            if(stat[index].tower_occupy[tower] == me) return estimate(index);
            stat[++tot] = stat[index];
            stat[tot].score = 0;
            stat[tot].expand = 0;
            memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
            stat[tot].rest_ball--;
            stat[tot].rest_cup--;
            stat[tot].rest_time -= cup_time;
            stat[tot].tower_power[tower][me] += 4;
            if(stat[tot].tower_power[tower][me] > stat[tot].tower_power[tower][enemy]) stat[tot].tower_occupy[tower] = me;
            stat[tot].father = index;
            stat[tot].action = PUSH_CUP;
            stat[index].child_status[PUSH_CUP] = tot;
            int t = tot;
            int score = estimate(tot);
            stat[t].score += score;
            return score;
        }
        default:
        {
            int j = action;
            int x = stat[index].x + dx[j];
            int y = stat[index].y + dy[j];
            //if(work_visited[x][y]) break;
            //work_visited[x][y] = true;
            stat[++tot] = stat[index];
            stat[tot].score = 0;
            stat[tot].expand = 0;
            memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
            stat[tot].score += move_weight;
            stat[tot].x = x;
            stat[tot].y = y;
            stat[tot].rest_time -= move_time;
            stat[tot].rest_square -= 1;
            stat[tot].action = j;
            stat[tot].father = index;
            stat[index].child_status[j] = tot;
            int t = tot;
            int score = estimate(tot);
            if(stat[t].graph_occupy[x][y] == enemy) score -= pass_weight;
            stat[t].score += score;
            return score;
        }
    }
}

//Monte Carlo Tree Search
void MCTS(int index)
{
    //cout<<index<<" ";
    //if this status can not do anything, return
    if(stat[index].rest_time <= min_time || stat[index].rest_square <= min_square) return;
    //stat[index].score = 0;
    //step1: do all of the possible choices and estimate them
    for(int i = 1; i <= 7; i++)
    {
        switch (i)
        {
            case OCCUPY:
            {
                int occupy_status = get_occupy_status(index, me);
                if(occupy_status == CANT_OCCUPY) break;
                if(stat[index].graph_occupy[stat[index].x][stat[index].y] == me ||
                    stat[index].graph_status[stat[index].x][stat[index].y] == STRONG_OCCUPY) break;
                stat[++tot] = stat[index];
                stat[tot].score = 0;
                stat[tot].expand = 0;
                memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
                stat[tot].graph_occupy[stat[tot].x][stat[tot].y] = me;
                stat[tot].graph_status[stat[tot].x][stat[tot].y] = occupy_status;
                stat[tot].father = index;
                stat[tot].action = OCCUPY;
                stat[index].child_status[OCCUPY] = tot;
                stat[tot].rest_time -= occupy_time;
                stat[tot].expand = 1;
                node n;
                n.index = tot;
                n.uct = 0;
                q.push(n);
                break;
            }
            case PUSH_BALL:
            {
                int tower = get_tower(stat[index].x, stat[index].y);
                if(tower == 0) break;
                if(stat[index].tower_occupy[tower] == me) break;
                if(stat[index].rest_ball <= 0) break;
                stat[++tot] = stat[index];
                stat[tot].score = 0;
                stat[tot].expand = 0;
                memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
                stat[tot].rest_ball--;
                stat[tot].rest_time -= ball_time;
                stat[tot].tower_power[tower][me]++;
                if(stat[tot].tower_power[tower][me] > stat[tot].tower_power[tower][enemy]) stat[tot].tower_occupy[tower] = me;
                stat[tot].father = index;
                stat[tot].action = PUSH_BALL;
                stat[index].child_status[PUSH_BALL] = tot;
                stat[tot].expand = 1;
                node n;
                n.index = tot;
                n.uct = 0;
                q.push(n);
                break;
            }
            case PUSH_CUP:
            {
                int tower = get_tower(stat[index].x, stat[index].y);
                if(tower == 0) break;
                if(stat[index].tower_occupy[tower] == me) break;
                if(!(stat[index].rest_ball >= 1 && stat[index].rest_cup >= 1)) break;
                stat[++tot] = stat[index];
                stat[tot].score = 0;
                stat[tot].expand = 0;
                memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
                stat[tot].rest_ball--;
                stat[tot].rest_cup--;
                stat[tot].rest_time -= cup_time;
                stat[tot].tower_power[tower][me] += 4;
                if(stat[tot].tower_power[tower][me] > stat[tot].tower_power[tower][enemy]) stat[tot].tower_occupy[tower] = me;
                stat[tot].father = index;
                stat[tot].action = PUSH_CUP;
                stat[index].child_status[PUSH_CUP] = tot;
                stat[tot].expand = 1;
                node n;
                n.index = tot;
                n.uct = 0;
                q.push(n);
                break;
            }
            default:
            {
                int x = stat[index].x + dx[i];
                int y = stat[index].y + dy[i];
                if(!check(x, y)) continue;
                //if(work_visited[x][y]) break;
                //work_visited[x][y] = true;
                stat[++tot] = stat[index];
                stat[tot].score = 0;
                stat[tot].expand = 0;
                memset(stat[tot].child_status, 0, sizeof(stat[tot].child_status));
                if(stat[tot].graph_occupy[x][y] == enemy) stat[tot].score -= pass_weight;
                stat[tot].x = x;
                stat[tot].y = y;
                stat[tot].rest_time -= move_time;
                stat[tot].rest_square -= 1;
                stat[tot].action = i;
                stat[tot].father = index;
                stat[index].child_status[i] = tot;
                stat[tot].expand = 1;
                node n;
                n.index = tot;
                n.uct = 0;
                q.push(n);
                //work_visited[x][y] = false;
                break;
            }
        }
    }
    for (int i = 1; i < 8; ++i)
    {
        if(stat[index].child_status[i] == 0) continue;
        int score = estimate(stat[index].child_status[i]);
        stat[stat[index].child_status[i]].score += score;
        stat[index].score += score;
    }
    //step2: choose the max UCT status and estimate it for some times
    //init UCT
    vector <node> v;
    while(!q.empty())
    {
        node n = q.top();
        q.pop();
        n.uct = uct(index, n.index);
        v.push_back(n);
    }
    for (int i = 0; i < v.size(); ++i)
    {
        q.push(v[i]);
    }
    v.clear();
    for (int i = 0; i < estimate_times; ++i)
    {
        node n = q.top();
        q.pop();
        stat[n.index].expand++;
        int score = estimate(n.index);
        stat[n.index].score += score;
        stat[index].score += score;
        n.uct = uct(index, n.index);
        q.push(n);
    }
    while(!q.empty()) q.pop();
    int max_expand = 0, max_index = 0;
    for (int i = 1; i <= 7; ++i)
    {
        if(max_expand < stat[stat[index].child_status[i]].expand)
        {
            max_expand = stat[stat[index].child_status[i]].expand;
            max_index = stat[index].child_status[i];
        }
    }
    //step3: choose the most chosen status and MCTS(status)
    std::cout << max_expand << " " << max_index << " : " << number2action(stat[max_index].action) << std::endl;
    MCTS(max_index);
}

