#include <iostream>
#include <cstdio>
#include <queue>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <ctime>

//define some settings
int max_square = 15; //the max square to go in a turn
int min_time = 0;
int min_square = 0;
int max_ball = 30;
int max_cup = 10;

//variables about time(ms)
int tot_time = 40000; //total time in a turn
int ball_time = 3000; //time cost when push a ball
int cup_time = 5000; //time cost when push a cup
int move_time = 1000; //time cost when move a square
int occupy_time = 1000; //time cost when occupy a square

//weight about actions
int occupy_weight_weak = 15;
int occupy_weight_strong = 20;
int push_ball_weight = 0;
int push_cup_weight = 0;
int occupy_tower_weight = 50;
int move_weight = 0;
int pass_weight = -1;
int visited_cost = -2;
int occupied_cost = -0;

//variables about estimate
float estimate_per_time = 0.001;
int estimate_per_square = 10;
int random_time = 500;
int random_step = 20;
#define CUP_ESTIMATE 20
#define MOVE_ESTIMATE 20
#define BALL_ESTIMATE 30
#define OCCUPY_ESTIMATE 30
#define ALL_ESTIMATE CUP_ESTIMATE + MOVE_ESTIMATE + BALL_ESTIMATE + OCCUPY_ESTIMATE

//players
#define RED 1
#define BLUE 2
int me, enemy;

//graph
#define EMPTY_SQUARE 0
#define RED_SQUARE 1
#define BLUE_SQUARE 2
#define EMPTY 0
#define STRONG 2
#define WEAK 1

bool tower_connected[10];
bool visited[10][10];
bool visited_strong[10][10];
bool work_visited[10][10];
int graph_occupy[10][10]; //who occupy one square
int graph_status[10][10]; //whether the square is strong or weak occupied
int tower_power[10][3];

//car status
int pos_x[3], pos_y[3];

//actions list
#define MAX_ACTIONS 3
#define MOVE 0
#define OCCUPY 1
#define PUSH_BALL 2
#define PUSH_CUP 3
#define MOVE_UP 4
#define MOVE_LEFT 5
#define MOVE_DOWN 6
#define MOVE_RIGHT 7

int dx[8] = {0, 0, 0, 0, -1, 0, 1, 0};
int dy[8] = {0, 0, 0, 0, 0, -1, 0, 1};

//occupy status list
#define CANT_OCCUPY 0
#define WEAK_OCCUPY 1
#define STRONG_OCCUPY 2


//search status struct
struct status
{
    int x;
    int y;
    int rest_time;
    int rest_square;
    int rest_cup;
    int rest_ball;
    int score;
    int weight;
    int occupy_status;
    int last_status_index;
    int action;
    bool operator < (const status &b) const
    {
        return (weight < b.weight) || (weight == b.weight && rest_time < b.rest_time);
    }
    bool operator == (const status &b) const
    {
        return x == b.x && y == b.y && rest_time == b.rest_time && rest_square == b.rest_square && rest_cup == b.rest_cup &&
        rest_ball == b.rest_ball && score == b.score && weight == b.weight && occupy_status == b.occupy_status &&
        last_status_index == b.last_status_index && action == b.action;
    }
};

std::priority_queue <status> q;

std::vector <status> statuses;

int random_action()
{
    int t = rand() % ALL_ESTIMATE + 1;
    if(t < CUP_ESTIMATE) return PUSH_CUP;
    t -= CUP_ESTIMATE;
    if(t < BALL_ESTIMATE) return PUSH_BALL;
    t -= BALL_ESTIMATE;
    if(t < OCCUPY_ESTIMATE) return OCCUPY;
    return rand() % 4 + 4;
}

void print_status(status stat)
{
    printf("x:%d;y:%d;rest_time:%d;rest_square:%d;rest_cup:%d;rest_ball:%d;score:%d;weight:%d;occupy_status:%d;"
           "last_status_index:%d\n",
            stat.x, stat.y, stat.rest_time, stat.rest_square, stat.rest_cup, stat.rest_ball, stat.score,
            stat.weight, stat.occupy_status, stat.last_status_index);
}

std::string number2action(int number)
{
    switch (number)
    {
        case OCCUPY:
            return "occupy";
        case PUSH_BALL:
            return "ball";
        case PUSH_CUP:
            return "cap";
        case MOVE_LEFT:
            return "left";
        case MOVE_RIGHT:
            return "right";
        case MOVE_UP:
            return "up";
        case MOVE_DOWN:
            return "down";
        default:
            return "";
    }
}

