int random_action()
{
    int t = rand() % ALL_ESTIMATE + 1;
    if(t < CUP_ESTIMATE) return PUSH_CUP;
    t -= CUP_ESTIMATE;
    if(t < BALL_ESTIMATE) return PUSH_BALL;
    t -= BALL_ESTIMATE;
    if(t < OCCUPY_ESTIMATE) return OCCUPY;
    return rand() % 4 + 4;
}

void occupy_dfs(int x, int y, int player)
{
    if(x <= 0 || x >= 8 || y <= 0 || y >= 10) return;
    if(graph_occupy[x][y] != player) return;
    if(visited[x][y]) return;
    visited[x][y] = true;
    if(get_tower(x, y) && tower_occupy[get_tower(x, y)] == player) tower_connected[get_tower(x, y)] = true;
    occupy_dfs(x + 1, y, player);
    occupy_dfs(x - 1, y, player);
    occupy_dfs(x, y + 1, player);
    occupy_dfs(x, y - 1, player);
}

int get_occupy_status(int x, int y, int player)
{
    int tower_count = 0;
    memset(tower_connected, 0, sizeof(tower_connected));
    memset(visited, 0, sizeof(visited));
    int t = graph_occupy[x][y];
    graph_occupy[x][y] = player;
    occupy_dfs(x, y, player);
    graph_occupy[x][y] = t;
    for (int k = 0; k < 10; ++k)
        if(tower_connected[k]) tower_count++;
    if(tower_count >= 3) return STRONG_OCCUPY;
    if(tower_count > 0) return WEAK_OCCUPY;
    return CANT_OCCUPY;
}

//sum the total square score for each player
void sum(int *blue, int *red)
{
    *blue = 0;
    *red = 0;
    for (int i = 1; i <= 7; i++)
        for (int j = 1; j <= 9; ++j)
        {
            if(graph_occupy[i][j] == BLUE)
            {
                if(graph_status[i][j] == WEAK_OCCUPY) *blue += occupy_weight_weak;
                else *blue += occupy_weight_strong;
            }
            else if(graph_occupy[i][j] == RED)
            {
                if(graph_status[i][j] == WEAK_OCCUPY) *red += occupy_weight_weak;
                else *red += occupy_weight_strong;
            }
        }
    for (int i = 0; i < 10; ++i)
    {
        if(tower_occupy[i] == RED) *red += occupy_tower_weight;
        if(tower_occupy[i] == BLUE) *blue += occupy_tower_weight;
    }
    //std::cout<<*red<<" "<<*blue<<std::endl;
}

bool check_action(status *stat, int action)
{
    if(action >= MOVE_UP && action <= MOVE_RIGHT) if(check(stat->x + dx[action], stat->y + dy[action])) return true;
    if(action == PUSH_CUP)
        if(get_tower(stat->x + dx[action], stat->y + dy[action]) && stat->rest_ball >= 1 && stat->rest_cup >= 1) return true;
    if(action == PUSH_BALL) if(get_tower(stat->x + dx[action], stat->y + dy[action]) && stat->rest_ball >= 1) return true;
    if(action == OCCUPY) if(get_occupy_status(stat->x + dx[action], stat->y + dy[action], me)) return true;
    return false;
}

status* new_status(status *parent)
{
    status *stat = new status;
    stat->rest_square = parent->rest_square;
    stat->rest_time = parent->rest_time;
    stat->rest_cup = parent->rest_cup;
    stat->rest_ball = parent->rest_ball;
    stat->x = parent->x;
    stat->y = parent->y;
    stat->expand = 0;
    memset(stat->child_status, 0, sizeof(stat->child_status));
    stat->score = 1;
    return stat;
}

