std::string number2action(int number)
{
    switch (number)
    {
        case OCCUPY:
            return "occupy";
        case PUSH_BALL:
            return "ball";
        case PUSH_CUP:
            return "cap";
        case MOVE_LEFT:
            return "left";
        case MOVE_RIGHT:
            return "right";
        case MOVE_UP:
            return "up";
        case MOVE_DOWN:
            return "down";
        default:
            return "";
    }
}

void print(int index)
{
    if(index == 0) return;
    print(stat[index].father);
    std::cout << index << number2action(stat[index].action) << std::endl;
}

void force_work(int index)
{
    if(stat[index].rest_time <= min_time || stat[index].rest_square <= min_square)
    {
        int red, blue, score;
        sum(&blue, &red);
        std::cout<<red<<" "<<blue<<std::endl;
        if(me == RED) score = red - blue;
        else score = blue - red;
        if(score > max_score)
        {
            max_score = score;
            max_index = index;
        }
        return;
    }
    for(int i = 1; i <= 7; i++)
    {
        switch (i)
        {
            case OCCUPY:
            {
                int occupy_status = get_occupy_status(stat[index].x, stat[index].y, me);
                if(occupy_status == CANT_OCCUPY) break;
                if(graph_occupy[stat[index].x][stat[index].y] == me || graph_status[stat[index].x][stat[index].y] == STRONG_OCCUPY)
                    break;
                stat[++tot] = stat[index];
                int t1 = graph_occupy[stat[tot].x][stat[tot].y];
                int t2 = graph_status[stat[tot].x][stat[tot].y];
                graph_occupy[stat[tot].x][stat[tot].y] = me;
                graph_status[stat[tot].x][stat[tot].y] = occupy_status;
                stat[tot].father = index;
                stat[tot].action = OCCUPY;
                stat[index].child_status[OCCUPY] = tot;
                stat[tot].rest_time -= occupy_time;
                force_work(tot);
                graph_occupy[stat[tot].x][stat[tot].y] = t1;
                graph_status[stat[tot].x][stat[tot].y] = t2;
                break;
            }
            case PUSH_BALL:
            {
                int tower = get_tower(stat[index].x, stat[index].y);
                if(tower == 0) break;
                if(tower_occupy[tower] == me) break;
                if(stat[index].rest_ball <= 0) break;
                stat[++tot] = stat[index];
                stat[tot].rest_ball--;
                stat[tot].rest_time -= ball_time;
                tower_power[tower][me]++;
                int t = tower_occupy[tower];
                if(tower_power[tower][me] > tower_power[tower][enemy]) tower_occupy[tower] = me;
                stat[tot].father = index;
                stat[tot].action = PUSH_BALL;
                stat[index].child_status[PUSH_BALL] = tot;
                force_work(tot);
                tower_power[tower][me]--;
                tower_occupy[tower] = t;
                break;
            }
            case PUSH_CUP:
            {
                int tower = get_tower(stat[index].x, stat[index].y);
                if(tower == 0) break;
                if(tower_occupy[tower] == me) break;
                if(!(stat[index].rest_ball >= 1 && stat[index].rest_cup >= 1)) break;
                stat[++tot] = stat[index];
                stat[tot].rest_ball--;
                stat[tot].rest_cup--;
                stat[tot].rest_time -= cup_time;
                tower_power[tower][me] += 4;
                int t = tower_occupy[tower];
                if(tower_power[tower][me] > tower_power[tower][enemy]) tower_occupy[tower] = me;
                stat[tot].father = index;
                stat[tot].action = PUSH_CUP;
                stat[index].child_status[PUSH_CUP] = tot;
                force_work(tot);
                tower_power[tower][me]-=4;
                tower_occupy[tower] = t;
                break;
            }
            default:
            {
                for (int j = 4; j < 8; ++j)
                {
                    int x = stat[index].x + dx[j];
                    int y = stat[index].y + dy[j];
                    if(!check(x, y)) continue;
                    if(work_visited[x][y]) break;
                    work_visited[x][y] = true;
                    stat[++tot] = stat[index];
                    stat[tot].x = x;
                    stat[tot].y = y;
                    stat[tot].rest_time -= move_time;
                    stat[tot].rest_square -= 1;
                    stat[tot].action = j;
                    stat[tot].father = index;
                    stat[index].child_status[j] = tot;
                    force_work(tot);
                    work_visited[x][y] = false;
                }
                break;
            }
        }
    }
}

