///sum the total score for each player
void sum(int index, int *blue, int *red)
{
    *blue = 0;
    *red = 0;
    for (int i = 1; i <= 7; i++)
        for (int j = 1; j <= 9; ++j)
        {
            if(stat[index].graph_occupy[i][j] == BLUE)
            {
                if(stat[index].graph_status[i][j] == WEAK_OCCUPY) *blue += occupy_weight_weak;
                else *blue += occupy_weight_strong;
            }
            else if(stat[index].graph_occupy[i][j] == RED)
            {
                if(stat[index].graph_status[i][j] == WEAK_OCCUPY) *red += occupy_weight_weak;
                else *red += occupy_weight_strong;
            }
        }
    for (int i = 1; i < 8; ++i)
    {
        if(stat[index].tower_occupy[i] == RED) *red += occupy_tower_weight;
        if(stat[index].tower_occupy[i] == BLUE) *blue += occupy_tower_weight;
        //*red += stat[index].tower_power[i][RED] * tower_power_weight;
        //*blue += stat[index].tower_power[i][BLUE] * tower_power_weight;
    }
    //std::cout<<*red<<" "<<*blue<<std::endl;
}

int get_score(int init, int index, int player)
{
    int red, blue, score, score_blue, score_red;
    sum(init, &score_blue, &score_red);
    sum(index, &blue, &red);
    //cout<<red<<" "<<blue<<endl;
    if(player == RED) score = red - score_red + score_blue - blue;
    else score = blue - score_blue + score_red - red;
    //cout<<score<<endl;
    return score;
}

///change the status of the block
void update_dfs(int index, int x, int y, int player, int tag)
{
    if(player == 0) return;
    if(x <= 0 || x >= 8 || y <= 0 || y >= 10) return;
    if(stat[index].graph_occupy[x][y] != player) return;
    if(visited_strong[x][y]) return;
    visited_strong[x][y] = true;
    stat[index].graph_status[x][y] = tag;
    update_dfs(index, x + 1, y, player, tag);
    update_dfs(index, x - 1, y, player, tag);
    update_dfs(index, x, y + 1, player, tag);
    update_dfs(index, x, y - 1, player, tag);
}

///update graph status(strong or weak)
///used after a tower status changed
void update_graph_status(int index)
{
    change_tower_square(index);
    memset(visited, 0, sizeof(visited));
    for (int i = 1; i < 8; ++i)
    {
        for (int j = 1; j < 10; ++j)
        {
            if(!visited[i][j])
            {
                int tower_count = 0;
                memset(tower_connected, 0, sizeof(tower_connected));
                occupy_dfs(index, i, j, stat[index].graph_occupy[i][j]);
                for (int k = 1; k < 8; ++k) if(tower_connected[k]) tower_count++;
                memset(visited_strong, 0, sizeof(visited_strong));
                if (tower_count >= strong_need_towers)
                    update_dfs(index, i, j, stat[index].graph_occupy[i][j], STRONG);
                else
                    update_dfs(index, i, j, stat[index].graph_occupy[i][j], WEAK);
            }
        }
    }
    clear_tower_square(index);
}

///dfs until depth is 3
int dfs(int init, int index, int depth)
{
    if(depth == 8 || stat[index].rest_time <= min_time || stat[index].rest_square <= min_square)
    {
        return get_score(init, index, me);
    }
    int max_score = -1000000;
    for(int i = 1; i < 8; i++)
    {
        stat[++tot] = stat[index];
        if(!check_action(tot, i))
        {
            tot--;
            continue;
        }
        switch (i)
        {
            case OCCUPY:
            {
                stat[tot].graph_occupy[stat[tot].x][stat[tot].y] = me;
                stat[tot].graph_status[stat[tot].x][stat[tot].y] = get_occupy_status(tot, me);
                stat[tot].rest_time -= occupy_time;
                update_graph_status(tot);
                break;
            }
            case PUSH_BALL:
            {
                stat[tot].rest_ball--;
                stat[tot].rest_time -= ball_time;
                stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me]++;
                stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                update_graph_status(tot);
                break;
            }
            case PUSH_CUP:
            {
                stat[tot].rest_ball--;
                stat[tot].rest_cup--;
                stat[tot].rest_time -= cup_time;
                stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me] += 4;
                stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                update_graph_status(tot);
                //cout<<stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)]<<endl;
                break;
            }
                ///move
            default:
            {
                stat[tot].rest_square--;
                stat[tot].rest_time -= move_time;
                stat[tot].x += dx[i];
                stat[tot].y += dy[i];
                if(stat[tot].graph_occupy[stat[tot].x][stat[tot].y] == enemy) stat[tot].score += pass_weight;
            }
        }
        max_score = max(dfs(init, tot, depth + 1), max_score);
        tot--;
    }
    return max_score;
}

///fully expand stat[index] and return the max estimate of the them
int simulate(int index)
{
    return dfs(index, index, 0);
}

///priority and three-depth estimate BFS
void work()
{
    while(!q.empty())
    {
        ///step1:choose the status which has the max weight
        node n = q.top();
        q.pop();
        ///if this status can not do anything, return and print
        if(stat[n.index].rest_time <= min_time || stat[n.index].rest_square <= min_square)
        {
            FILE *fout = fopen("/home/robomaster/RM/test.txt", "w");
            fprintf(fout, "# tower_power,RED=1,BLUE=2\n");
            for (int i = 1; i <= 7; i++)
                fprintf(fout, "%d ", stat[n.index].tower_power[i][RED]);
            fprintf(fout, "\n");
            for (int i = 1; i <= 7; i++)
                fprintf(fout, "%d ", stat[n.index].tower_power[i][BLUE]);
            fprintf(fout, "\n# car_pos\n");
            if(me == RED)
            {
                fprintf(fout, "%d %d\n%d %d", stat[n.index].x, stat[n.index].y, pos_x[BLUE], pos_y[BLUE]);
            }
            else
            {
                fprintf(fout, "%d %d\n%d %d", pos_x[RED], pos_y[RED], stat[n.index].x, stat[n.index].y);
            }
            fprintf(fout, "\n# graph occupy\n");
            for (int i = 1; i <= 7; i++)
            {
                for (int j = 1; j <= 9; j++)
                    fprintf(fout, "%d ", stat[n.index].graph_occupy[i][j]);
                fprintf(fout, "\n");
            }
            fprintf(fout, "# me\n");
            fprintf(fout, "%d", enemy);
            fclose(fout);
            print(n.index);
            while(!q.empty()) q.pop();
            return;
        }
        ///step2:expand every possible choice of this status
        ///step3:simulate many times to get its average reward
        for(int i = 1; i < 8; i++)
        {
            if(!check_action(n.index, i)) continue;
            tot++;
            stat[tot] = stat[n.index];
            stat[tot].action = i;
            stat[tot].father = n.index;
            switch (i)
            {
                case OCCUPY:
                {
                    stat[tot].graph_occupy[stat[tot].x][stat[tot].y] = me;
                    stat[tot].graph_status[stat[tot].x][stat[tot].y] = get_occupy_status(tot, me);
                    stat[tot].rest_time -= occupy_time;
                    update_graph_status(tot);
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                case PUSH_BALL:
                {
                    stat[tot].rest_ball--;
                    stat[tot].rest_time -= ball_time;
                    stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me]++;
                    stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                    update_graph_status(tot);
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                case PUSH_CUP:
                {
                    stat[tot].rest_ball--;
                    stat[tot].rest_cup--;
                    stat[tot].rest_time -= cup_time;
                    stat[tot].tower_power[get_tower(stat[tot].x, stat[tot].y)][me] += 4;
                    stat[tot].tower_occupy[get_tower(stat[tot].x, stat[tot].y)] = get_tower_occupy(tot, get_tower(stat[tot].x, stat[tot].y));
                    update_graph_status(tot);
                    stat[tot].score = get_score(1, tot, me);
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                    break;
                }
                    ///move
                default:
                {
                    stat[tot].rest_square--;
                    stat[tot].rest_time -= move_time;
                    stat[tot].x += dx[i];
                    stat[tot].y += dy[i];
                    if(stat[tot].graph_occupy[stat[tot].x][stat[tot].y] == enemy) stat[tot].score += pass_weight;
                    stat[tot].weight = simulate(tot) + stat[tot].score;
                }
            }
            ///step4:add this status to the queue
            q.push(node{tot, stat[tot].weight});
        }
    }
}

int main(int argc, char** argv)
{
    ///load origin status from the text
    FILE *fp = fopen("/home/robomaster/RM/testex.txt", "r");
    srand((unsigned int) time(0));
    fscanf(fp, "# tower_power,RED=1,BLUE=2\n");
    for (int i = 1; i <= 7; i++)
        fscanf(fp, "%d", &stat[1].tower_power[i][RED]);
    for (int i = 1; i <= 7; i++)
        fscanf(fp, "%d", &stat[1].tower_power[i][BLUE]);
    for (int i = 1; i <= 7; ++i)
        stat[1].tower_occupy[i] = get_tower_occupy(1, i);
    fscanf(fp, "\n# car_pos\n");
    fscanf(fp, "%d %d %d %d", &pos_x[RED], &pos_y[RED], &pos_x[BLUE], &pos_y[BLUE]);
    fscanf(fp, "\n# graph occupy\n");
    for (int i = 1; i <= 7; i++)
        for (int j = 1; j <= 9; j++)
            fscanf(fp, "%d", &stat[1].graph_occupy[i][j]);
    fscanf(fp, "\n# graph status\n");
    for (int i = 1; i <= 7; i++)
        for (int j = 1; j <= 9; j++)
            fscanf(fp, "%d", &stat[1].graph_status[i][j]);
    fscanf(fp, "\n# me\n");
    fscanf(fp, "%d", &me);
    fclose(fp);
    ///who i am
    if (me == BLUE) enemy = RED;
    else enemy = BLUE;
    ///set origin status
    stat[1].x = pos_x[me];
    stat[1].y = pos_y[me];
    stat[1].rest_time = tot_time;
    stat[1].score = 0;
    stat[1].rest_square = max_square;
    stat[1].rest_ball = max_ball;
    stat[1].rest_cup = max_cup;
    update_graph_status(1);
    ///WARNING:C++11
    q.push(node{1, 0});
    tot = 1;
    work();
    return 0;
}

