typedef struct
{
    struct castle_energy
    {
        uint8_t energy[2];
    } castle_energy[7];

    struct region_occupy
    {
        uint8_t status : 2; // 0 = no one, 1 = weak, 2 = strong
        uint8_t belong : 2; // 0 = no one, 1 = red, 2 = blue
        uint8_t have_robot : 2; // same as belong // resv
        uint8_t resv : 2;
    } region_occupy[9][7];

    uint8_t car_location[2];
    uint8_t round_remain_tick;
    uint8_t round_remain_cnt;
    uint8_t round_team;
    int16_t realtime_score[2];
} summer_camp_info_t;

rm_msgs::status get_status(summer_camp_info_t info, int me)
{
    rm_msgs::status t;
    std_msgs::UInt8 n;
    for(int i = 0; i < 8; i++)
    {
        n.data = info.castle_energy[i].energy[0];
        t.tower_power_red.push_back(n);
    }
    for(int i = 0; i < 8; i++)
    {
        n.data = info.castle_energy[i].energy[1];
        t.tower_power_blue.push_back(n);
    }
