    t.car_pos_x_blue.data = (info.car_location[1] & 15) + 1;
    t.car_pos_y_blue.data = (info.car_location[1] >> 4) + 1;
    t.round_team.data = info.round_team + 1;
    t.me.data = me;
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][0].belong;
        t.graph_occupy_1.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][1].belong;
        t.graph_occupy_2.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][2].belong;
        t.graph_occupy_3.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][3].belong;
        t.graph_occupy_4.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][4].belong;
        t.graph_occupy_5.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][5].belong;
        t.graph_occupy_6.push_back(n);
    }
    for(int i = 0; i < 9; i++)
    {
        n.data = info.region_occupy[i][6].belong;
        t.graph_occupy_7.push_back(n);
    }
    return t;
}

